var raw = String(Inputs.email == null ? '' : Inputs.email).trim();
// The three shapes a paste actually arrives in: a mailto: link, an angle-bracketed
// address out of a mail client, and the plain thing with stray whitespace.
if (raw.slice(0, 7).toLowerCase() === 'mailto:') raw = raw.slice(7).trim();
if (raw.charAt(0) === '<' && raw.charAt(raw.length - 1) === '>') raw = raw.slice(1, -1).trim();
// The local part is case-sensitive per RFC 5321 and case-insensitive at every mail host
// anyone uses. Lower-casing the whole address is what makes two sign-ups the same person.
var email = raw.toLowerCase();
var at = email.lastIndexOf('@');
Outputs.email = email;
Outputs.domain = at === -1 ? '' : email.slice(at + 1);
Outputs.isValid = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/.test(email);
